sys_script_include.script:
function IsValidPluginList(strParam)
{
	strParam = GetStringValue(strParam);
	var aList = GetArrayValue(strParam);
	for (var nElement = 0; nElement < aList.length; nElement++)
	{
		var strElement = aList[nElement];
		var bValid = false;
		if (IsValidPluginId(strElement) == true)
		{
			bValid = true;
		}
		else if (IsValidAppName(strElement) == true)
		{
			bValid = true;
		}
		if (bValid == false)
		{
			return false;
		}
	}
	return true;
}
